CREATE TABLE activity_logs (id BIGINT NOT NULL AUTO_INCREMENT,workspace_id BIGINT NOT NULL,actor_user_id BIGINT NOT NULL,activity_type VARCHAR(50) NOT NULL,entity_type VARCHAR(30) NOT NULL,entity_id BIGINT NOT NULL,message VARCHAR(500) NOT NULL,created_at DATETIME(6) NOT NULL,PRIMARY KEY(id),INDEX idx_activity_logs_workspace_created(workspace_id,created_at),INDEX idx_activity_logs_actor_user(actor_user_id),CONSTRAINT fk_activity_logs_workspace FOREIGN KEY(workspace_id) REFERENCES workspaces(id),CONSTRAINT fk_activity_logs_actor FOREIGN KEY(actor_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
